import { Capabilities } from "@/components/marketing/capabilities";
import { Hero } from "@/components/marketing/hero";
import { HowItWorks } from "@/components/marketing/how-it-works";
import { LiveExample } from "@/components/marketing/live-example";
import { ClosingCta, PrivacyNote } from "@/components/marketing/privacy-note";
import { Proof } from "@/components/marketing/proof";
import { RISK_LABEL } from "@/lib/contracts/score";
import { scoreText } from "@/lib/scoring/score";

/**
 * Landing page.
 *
 * The live example is generated by the real engine at build time, so the number
 * on the marketing page cannot drift from the product. That is the whole point
 * of §2 of the plan: prove it works without asking the judge to type.
 */

const DEMO_TEXT =
  "Selamat siang Bu, ini undangan pernikahan anak kami. Mohon dibuka ya file Undangan-Pernikahan.apk yang saya kirim, isinya lengkap dengan lokasi acara.";

export default function LandingPage() {
  const demo = scoreText({ text: DEMO_TEXT });

  return (
    <>
      <Hero score={demo.score} risk={RISK_LABEL[demo.risk]} />
      <LiveExample score={demo.score} risk={RISK_LABEL[demo.risk]} />
      <HowItWorks />
      <Capabilities />
      <Proof />
      <PrivacyNote />
      <ClosingCta />
    </>
  );
}
